    let step_start = Instant::now();
    let result = match execute_step(
        step,
        project_root,
        context,
        global_env,
        &exec_options,
        output_callback,
    ) {
        Ok(result) => result,
        Err(e) => {
            warn!("Step '{}' errored: {}", step_name, e);
            StepResult::failure(step_name, step_start.elapsed(), e.to_string(), None)
